CREATE TABLE IF NOT EXISTS aw_capabilities(business_id TEXT NOT NULL,agent TEXT NOT NULL,kind TEXT NOT NULL,scope_note TEXT NOT NULL,available INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(business_id,agent,kind),FOREIGN KEY(business_id,agent) REFERENCES bf_ai_assignments(business_id,agent));
CREATE TABLE IF NOT EXISTS aw_jobs(business_id TEXT NOT NULL,id TEXT NOT NULL,deal_id TEXT NOT NULL,entry_key TEXT NOT NULL,kind TEXT NOT NULL,due_day TEXT NOT NULL,priority INTEGER NOT NULL,agent TEXT,task_id TEXT REFERENCES tasks(id),state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_at TEXT,error_code TEXT,generation INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,entry_key),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id),FOREIGN KEY(business_id,id,task_id) REFERENCES aw_tasks(business_id,job_id,task_id));
CREATE TABLE IF NOT EXISTS aw_tasks(task_id TEXT PRIMARY KEY REFERENCES tasks(id),business_id TEXT NOT NULL,job_id TEXT NOT NULL,UNIQUE(business_id,job_id,task_id),FOREIGN KEY(business_id,job_id) REFERENCES aw_jobs(business_id,id));
CREATE TABLE IF NOT EXISTS aw_handoffs(business_id TEXT NOT NULL,id TEXT NOT NULL,job_id TEXT NOT NULL,entry_key TEXT NOT NULL,from_agent TEXT NOT NULL,to_agent TEXT NOT NULL,from_kind TEXT NOT NULL,to_kind TEXT NOT NULL,from_task TEXT NOT NULL REFERENCES tasks(id),to_task TEXT NOT NULL REFERENCES tasks(id),reason TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,entry_key),FOREIGN KEY(business_id,job_id) REFERENCES aw_jobs(business_id,id),FOREIGN KEY(business_id,job_id,from_task) REFERENCES aw_tasks(business_id,job_id,task_id),FOREIGN KEY(business_id,job_id,to_task) REFERENCES aw_tasks(business_id,job_id,task_id));
CREATE TABLE IF NOT EXISTS aw_changes(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),id TEXT NOT NULL,entry_key TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,snapshot TEXT NOT NULL,status TEXT NOT NULL,approved_by TEXT,approved_at TEXT,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,entry_key));
CREATE TABLE IF NOT EXISTS aw_events(id INTEGER PRIMARY KEY,business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),ref TEXT NOT NULL,event TEXT NOT NULL,actor TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS aw_task_scope_insert BEFORE INSERT ON aw_tasks WHEN NOT EXISTS(SELECT 1 FROM wf_tasks w JOIN aw_jobs j ON j.business_id=w.business_id AND j.deal_id=w.deal_id WHERE j.business_id=NEW.business_id AND j.id=NEW.job_id AND w.task_id=NEW.task_id) BEGIN SELECT RAISE(ABORT,'work_scope_mismatch'); END;
CREATE TRIGGER IF NOT EXISTS aw_task_scope_update BEFORE UPDATE ON aw_tasks WHEN NOT EXISTS(SELECT 1 FROM wf_tasks w JOIN aw_jobs j ON j.business_id=w.business_id AND j.deal_id=w.deal_id WHERE j.business_id=NEW.business_id AND j.id=NEW.job_id AND w.task_id=NEW.task_id) BEGIN SELECT RAISE(ABORT,'work_scope_mismatch'); END;
